from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.oam.mzoam.mzoam_base import MzoamBaseClass

logger = BackgroundLogger.Instance()


class Reset(MzoamBaseClass):
    """
    Reset
    """
    def __init__(self):
        super(Reset, self).__init__()

    def reset(self, **kwargs):
        """
        Function to rest
        """
        operation = kwargs.pop("operation", "''")
        logger.debug("Performing operation  {}...".format(operation.upper().replace("_", " ")))
        try:
            getattr(self, "_{}".format(operation.lower()))(**kwargs)
        except AttributeError:
            raise Exception("Operation {} not supported".format(operation))

    def _reset_site(self, **kwargs):
        alias = kwargs.get('alias')
        self.mzom_client.reset_site(session=alias)
